class TrucModel {
  final int stt;
  final String tenTruc;
  final String tenNgan;
  final String amDuong;
  final String hanh;
  final String yNghiaNguyenVan;
  final String uiGopText;

  const TrucModel({
    required this.stt,
    required this.tenTruc,
    required this.tenNgan,
    required this.amDuong,
    required this.hanh,
    required this.yNghiaNguyenVan,
    required this.uiGopText,
  });

  Map<String, dynamic> toJson() => {
    'stt': stt,
    'name': tenTruc,
    'short_name': tenNgan,
    'polarity': amDuong,
    'hanh': hanh,
    'meaning_raw': yNghiaNguyenVan,
    'ui_gop_text': uiGopText,
  };
}

class SaoModel {
  final int stt;
  final String tenDayDu;
  final String tenNgan;
  final String hanh;
  final String lyTrung;
  final String headerLine;
  final String directionLine;
  final String detailsLine;
  final String nenLam;
  final String kiengCu;
  final String ngoaiLe;
  final List<String> poem;
  final String uiRenderText;

  const SaoModel({
    required this.stt,
    required this.tenDayDu,
    required this.tenNgan,
    required this.hanh,
    required this.lyTrung,
    required this.headerLine,
    required this.directionLine,
    required this.detailsLine,
    required this.nenLam,
    required this.kiengCu,
    required this.ngoaiLe,
    required this.poem,
    required this.uiRenderText,
  });

  Map<String, dynamic> toJson() => {
    'stt': stt,
    'full_name': tenDayDu,
    'short_name': tenNgan,
    'hanh': hanh,
    'ly_trung': lyTrung,
    'header_line': headerLine,
    'direction_line': directionLine,
    'details_line': detailsLine,
    'nen_lam': nenLam,
    'kieng_cu': kiengCu,
    'ngoai_le': ngoaiLe,
    'poem': poem,
    'ui_render_text': uiRenderText,
  };
}

