  /// Thuật toán tính Thập Nhị Trực
  static TrucModel calculateTruc(int lunarMonth, String dayChi) {
    String cleanChi = dayChi.trim().split(' ').last;
    int dayChiIdx = branches.indexOf(cleanChi);
    if (dayChiIdx == -1) dayChiIdx = 0;
    
    int baseChiIdx = (lunarMonth + 1) % 12;
    int trucIdx = (dayChiIdx - baseChiIdx) % 12;
    if (trucIdx < 0) trucIdx += 12;
    
    String trucName = trucNames[trucIdx];
    return trucMap[trucName] ?? trucMap['Kiến']!;
  }

  /// Thuật toán tính Nhị Thập Bát Tú
  /// Mốc cố định: 01/01/1995 là Chủ Nhật, Sao Hư (STT 11)
  static SaoModel calculateSao(int day, int month, int year) {
    final refDate = DateTime(1995, 1, 1);
    final targetDate = DateTime(year, month, day);
    final diffDays = targetDate.difference(refDate).inDays;
    
    int rem = diffDays % 28;
    if (rem < 0) rem += 28;
    
    int starNum = rem + 11;
    if (starNum > 28) {
      starNum -= 28;
    }
    
    return saoMap[starNum] ?? saoMap[11]!;
  }
}
